question.solution:
class ToolBox:
    def __init__(self, ttl=60, rate_limit=3):
        self.ttl = ttl
        self.rate_limit = rate_limit
        self.now = 0
        self._tools = {}
        self._cache = {}
        self._counts = {}
        self._calls = 0
        self._hits = 0
        self._blocked = 0

    def register(self, name, fn):
        self._tools[name] = fn
        return self

    @staticmethod
    def _key(name, args, kwargs):
        return name + '|' + repr(args) + '|' + repr(sorted(kwargs.items()))

    def call(self, name, *args, **kwargs):
        if name not in self._tools:
            return {'error': f'未知工具 {name}'}
        key = self._key(name, args, kwargs)
        cached = self._cache.get(key)
        if cached is not None and self.now - cached[0] <= self.ttl:
            self._hits += 1
            return cached[1]
        served = self._counts.get(name, 0)
        if served >= self.rate_limit:
            self._blocked += 1
            return {'error': '调用过于频繁'}
        self._counts[name] = served + 1
        self._calls += 1
        result = self._tools[name](*args, **kwargs)
        self._cache[key] = (self.now, result)
        return result

    def stats(self):
        return {
            'calls': self._calls,
            'hits': self._hits,
            'blocked': self._blocked,
            'tools': sorted(self._tools),
        }


counter = {'n': 0}


def slow_add(a, b):
    counter['n'] += 1
    return a + b


box = ToolBox(ttl=60, rate_limit=3)
box.register('add', slow_add)
print(box.call('add', 1, 2))
print(box.call('add', 1, 2))
print('真实执行次数：', counter['n'])
print(box.stats())
box.now = 100
print(box.call('add', 1, 2))
print('缓存过期后执行次数：', counter['n'])
box.now = 1000
print(box.call('add', 5, 5), box.call('add', 6, 6))
print(box.call('add', 7, 7))
print(box.stats())

